+func Test_deviceLogin_savesSSHHost(t *testing.T) {
+	keyring.MockInit()
+
+	tests := []struct {
+		name     string
+		args     string
+		detected bool
+	}{
+		{name: "saves --ssh-hostname", args: " --ssh-hostname ssh.gl.io"},
+		{name: "saves the remote's host when the instance reports it as its SSH host", detected: true},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			t.Chdir(t.TempDir())
+			require.NoError(t, exec.Command("git", "init").Run())
+			require.NoError(t, exec.Command("git", "remote", "add", "origin", "git@ssh.gl.io:owner/repo.git").Run())
+
+			execLogin, hostname, cfg, tc := oauthLoginExec(t, newOAuthServer(t))
+			tc.MockProjects.EXPECT().
+				GetProject("owner/repo", gomock.Any(), gomock.Any()).
+				Return(&gitlab.Project{SSHURLToRepo: "git@ssh.gl.io:owner/repo.git"}, nil, nil).
+				MaxTimes(1)
+			out, err := execLogin("--hostname " + hostname + " --device" + tt.args)
+			require.NoError(t, err)
+
+			got, err := cfg.Get(hostname, "ssh_host")
+			require.NoError(t, err)
+			assert.Equal(t, "ssh.gl.io", got)
+			if tt.detected {
+				assert.Contains(t, out.ErrBuf.String(), "Set the SSH host of "+hostname+" to ssh.gl.io")
+			} else {
+				assert.NotContains(t, out.ErrBuf.String(), "Set the SSH host")
+			}
+		})
+	}
+}
