+// saveSSHHost saves the --ssh-hostname value as hostname's ssh_host, or else
+// an SSH host the repository's remotes confirm. Interactive logins skip the
+// detection because their SSH-hostname prompt already suggests a value.
+func saveSSHHost(ctx context.Context, opts *LoginOptions, cfg config.Config, hostname string, isSelfHosted bool) error {
+	if opts.SSHHostname == "" {
+		if opts.Interactive || !isSelfHosted {
+			return nil
+		}
+		if saved, _ := cfg.Get(hostname, "ssh_host"); saved != "" {
+			return nil
+		}
+		detected := detectConfirmedSSHHost(ctx, opts, hostname)
+		if detected == "" {
+			return nil
+		}
+		if err := cfg.Set(hostname, "ssh_host", detected); err != nil {
+			return err
+		}
+		opts.IO.LogErrorf("%s Set the SSH host of %s to %s, taken from this repository's remotes.\n", opts.IO.Color().GreenCheck(), hostname, detected)
+		return nil
+	}
+	if opts.SSHHostname == hostname {
+		return nil
+	}
+	return cfg.Set(hostname, "ssh_host", opts.SSHHostname)
+}
+
+// detectConfirmedSSHHost returns the host of an SSH remote whose project on
+// hostname has that host in its SSH clone URL, or "" if no remote has one.
+// Unlike detectSSHHost, nobody reviews the result before it is saved, and a
+// wrong ssh_host would send another instance's remotes to hostname.
+func detectConfirmedSSHHost(ctx context.Context, opts *LoginOptions, hostname string) string {
+	remotes, err := git.Remotes()
+	if err != nil {
+		dbg.Debugf("Not detecting the SSH host of %s, could not read the Git remotes: %v", hostname, err)
+		return ""
+	}
+	apiClient, err := opts.apiClient(hostname)
+	if err != nil {
+		dbg.Debugf("Not detecting the SSH host of %s, could not create an API client: %v", hostname, err)
+		return ""
+	}
+
+	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
+	defer cancel()
+
+	for _, remote := range remotes {
+		if remote.FetchURL == nil || remote.FetchURL.Scheme != "ssh" {
+			continue
+		}
+		remoteHost := glinstance.NormalizeHostname(remote.FetchURL.Hostname())
+		if remoteHost == "" || remoteHost == glinstance.NormalizeHostname(hostname) {
+			continue
+		}
+
+		projectPath := strings.TrimLeft(git.StripDotGit(remote.FetchURL.Path), "/")
+		project, _, err := apiClient.Lab().Projects.GetProject(projectPath, nil, gitlab.WithContext(ctx))
+		if err != nil {
+			dbg.Debugf("Skipping remote %s for the SSH host of %s, could not get project %s: %v", remote.Name, hostname, projectPath, err)
+			continue
+		}
+		cloneURL, err := git.ParseURL(project.SSHURLToRepo)
+		if err != nil {
+			dbg.Debugf("Skipping remote %s for the SSH host of %s, could not parse SSH clone URL %q: %v", remote.Name, hostname, project.SSHURLToRepo, err)
+			continue
+		}
+		if glinstance.NormalizeHostname(cloneURL.Hostname()) == remoteHost {
+			return remoteHost
+		}
+		dbg.Debugf("Skipping remote %s for the SSH host of %s, the SSH clone URL of %s is on %s", remote.Name, hostname, projectPath, cloneURL.Hostname())
+	}
+
+	return ""
+}
